Claim c = queue.claim(taskId, owner, now, leaseMs);
if (!c.acquired) return;
try {
  Budget b = budget.forResearchSlice();
  Cursor cur = Cursor.parse(c.cursorJson);
  while (b.hasTime() && cur.hasNext()) {
      processOne(cur);
      cur.advance();
      if (cur.pageBoundary()) queue.checkpoint(c, cur);
      if (realtimePressure()) {
          queue.yield(c, cur, "REALTIME_PREEMPTED");
          return;
      }
  }
  if (cur.done()) queue.complete(c, outputHash);
  else queue.retry(c, cur, "MONOTONIC_SLICE_EXHAUSTED");
} catch(Throwable t) {
  queue.retryOrTerminal(c, cursor, normalize(t));
}
